parameters.jsCode:
// Два режими:
// 1) БОЙОВИЙ: нода 'Claude Haiku classify' увімкнена — structured output гарантує валідний JSON (A9).
// 2) STUB (тимчасово, поки немає Anthropic-кредитів): Claude-ноди вимкнені,
//    вердикт — груба евристика, confidence 0.55 => все йде в review-гілку.
//    prompt_version='stub-no-llm' дозволяє потім повернути ці айтеми в чергу:
//    UPDATE seen_items SET status='pending' WHERE item_uid IN
//      (SELECT item_uid FROM items_log WHERE event='classified' AND prompt_version='stub-no-llm');
let resp = null;
try { resp = $('Claude Haiku classify').first().json; } catch (e) { resp = null; }
const t = $input.first().json; // thresholds row
let verdict, meta;
if (resp && Array.isArray(resp.content)) {
  if (resp.stop_reason === 'refusal') { throw new Error('classifier refusal: ' + JSON.stringify(resp.stop_details || {})); }
  const text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
  verdict = JSON.parse(text);
  meta = { prompt_version: 'rfp-classifier-v1',
    cache_read_input_tokens: resp.usage ? resp.usage.cache_read_input_tokens : null,
    cache_creation_input_tokens: resp.usage ? resp.usage.cache_creation_input_tokens : null };
} else {
  const item = $('Unwrap payload').first().json;
  const hay = ((item.title || '') + ' ' + (item.body || '')).toLowerCase();
  const cat = /request for proposal|rfp|proposals? (by|due)|tender|bounty/.test(hay) ? 'RFP'
    : /grant|retro(active)? funding|applications? (open|are open)|apply by/.test(hay) ? 'GRANT'
    : /raised|series [abc]|tvl|treasury|funding|budget/.test(hay) ? 'FUNDING' : 'NOISE';
  verdict = { is_rfp: cat !== 'NOISE', confidence: 0.55, category: cat,
    canonical_project: item.ecosystem || '?', canonical_title: (item.title || '').slice(0, 80),
    reason: 'STUB: без LLM (немає Anthropic-кредитів) — категорія за ключовими словами' };
  meta = { prompt_version: 'stub-no-llm' };
}
return [{ json: { ...verdict, threshold: t.threshold, band_low: t.band_low, ...meta } }];

